const input = $input.first().json.body || $input.first().json;

const formatTime = (seconds) => {
  if (!seconds || seconds <= 0) return '0m 0s';
  const mins = Math.floor(seconds / 60);
  const secs = Math.round(seconds % 60);
  if (mins === 0) return `${secs}s`;
  return `${mins}m ${secs}s`;
};

const formatScore = (score) => (parseFloat(score) || 0).toFixed(1);

const formatWhatsAppLink = (phone) => {
  if (!phone) return '';
  const cleaned = phone.toString().replace(/\D/g, '');
  if (cleaned.startsWith('0')) return '62' + cleaned.substring(1);
  if (cleaned.startsWith('62')) return cleaned;
  return '62' + cleaned;
};

const overall = parseFloat(input.scores?.overall) || 0;
const technical = parseFloat(input.scores?.technical) || 0;
const psikotes = parseFloat(input.scores?.psikotes) || 0;

const timerPersonal = parseInt(input.timer?.personal) || 0;
const timerTechnical = parseInt(input.timer?.technical) || 0;
const timerPsikotes = parseInt(input.timer?.psikotes) || 0;
const timerTotal = parseInt(input.timer?.total) || (timerPersonal + timerTechnical + timerPsikotes);

let kategori, kategoriEmoji, headerBg, headerBorder, badgeBg, badgeBorder, textColor, priority, followUp;

if (overall >= 8) {
  kategori = 'LULUS'; kategoriEmoji = '✅'; headerBg = '#d1fae5'; headerBorder = '#10b981';
  badgeBg = '#d1fae5'; badgeBorder = '#10b981'; textColor = '#047857'; priority = 'HIGH';
  followUp = '🔥 KANDIDAT SANGAT POTENSIAL! Score 8-10. Segera jadwalkan interview dalam 24-48 jam.';
} else if (overall >= 5) {
  kategori = 'REVIEW'; kategoriEmoji = '⚠️'; headerBg = '#fef3c7'; headerBorder = '#f59e0b';
  badgeBg = '#fef3c7'; badgeBorder = '#f59e0b'; textColor = '#b45309'; priority = 'MEDIUM';
  followUp = '⚡ PERLU EVALUASI LANJUT! Score 5-7.9. Pertimbangkan untuk interview dengan fokus pada area yang perlu ditingkatkan.';
} else {
  kategori = 'BELUM LULUS'; kategoriEmoji = '❌'; headerBg = '#fee2e2'; headerBorder = '#ef4444';
  badgeBg = '#fee2e2'; badgeBorder = '#ef4444'; textColor = '#b91c1c'; priority = 'LOW';
  followUp = '📋 Kandidat belum memenuhi kriteria minimum (score < 5). Simpan untuk referensi atau kirim email penolakan yang sopan.';
}

let speedEval, speedColor, speedIcon;
if (timerTotal <= 900) { speedEval = 'Sangat Cepat'; speedColor = '#059669'; speedIcon = '🚀'; }
else if (timerTotal <= 1500) { speedEval = 'Cepat & Ideal'; speedColor = '#0284c7'; speedIcon = '✅'; }
else if (timerTotal <= 2400) { speedEval = 'Normal'; speedColor = '#6b7280'; speedIcon = '⏱️'; }
else { speedEval = 'Lambat'; speedColor = '#dc2626'; speedIcon = '🐢'; }

let technicalAnalysis, psikotesAnalysis;
if (technical >= 8) technicalAnalysis = '💪 Excellent - Kemampuan teknis sangat baik';
else if (technical >= 6) technicalAnalysis = '👍 Good - Kemampuan teknis memadai';
else if (technical >= 4) technicalAnalysis = '📚 Fair - Perlu peningkatan skill teknis';
else technicalAnalysis = '⚠️ Needs Improvement - Skill teknis masih kurang';

if (psikotes >= 8) psikotesAnalysis = '🌟 Excellent - Soft skill & attitude sangat baik';
else if (psikotes >= 6) psikotesAnalysis = '👍 Good - Soft skill memadai';
else if (psikotes >= 4) psikotesAnalysis = '📝 Fair - Perlu evaluasi lebih lanjut';
else psikotesAnalysis = '⚠️ Concern - Ada potensi masalah attitude';

const whatsappNumber = formatWhatsAppLink(input.applicant?.whatsapp);

return {
  id: input.applicant?.id || '-',
  nama: input.applicant?.nama || '-',
  email: input.applicant?.email || '-',
  whatsapp: input.applicant?.whatsapp || '-',
  status: input.applicant?.status || '-',
  statusLabel: input.applicant?.statusLabel || '-',
  kategori, kategoriEmoji, headerBg, headerBorder, badgeBg, badgeBorder, textColor, priority,
  overallScore: formatScore(overall),
  technicalScore: formatScore(technical),
  psikotesScore: formatScore(psikotes),
  technicalAnalysis, psikotesAnalysis,
  timerPersonal: formatTime(timerPersonal),
  timerTechnical: formatTime(timerTechnical),
  timerPsikotes: formatTime(timerPsikotes),
  timerTotal: formatTime(timerTotal),
  timerTotalSeconds: timerTotal,
  speedEval, speedColor, speedIcon,
  speedDisplay: `${speedIcon} ${speedEval}`,
  technicalCorrect: input.details?.technicalCorrect || 0,
  technicalTotal: input.details?.technicalTotal || 5,
  recommendation: input.details?.recommendation || followUp,
  technicalContribution: formatScore(input.details?.technicalContribution || (technical * 0.7)),
  psikotesContribution: formatScore(input.details?.psikotesContribution || (psikotes * 0.3)),
  followUp,
  whatsappLink: whatsappNumber ? `https://wa.me/${whatsappNumber}` : '',
  emailLink: `mailto:${input.applicant?.email || ''}`,
  adminLink: 'https://recruitment.rayandra.com/admin/',
  timestamp: new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }),
  timestampShort: new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })
};
